<?php
namespace App\Console\Commands; use App\Services\Dapcode\CodeMinifierService; use Illuminate\Console\Command; use Illuminate\Support\Str; class CodeStatusCommand extends Command { protected $signature = 'code:status {target=all : Target: "all", "modules", "aegisguard", "routes" (termasuk middleware, helper, kernel & portofolio), module name (e.g. "Achievement"), or custom path} {--minified : Only show minified files} {--original : Only show non-minified / original files}'; protected $description = 'Check minify/unminify status, line counts, and SourceMap Vault status across project files'; public function handle(CodeMinifierService $minifier) { $target = (string) $this->argument('target'); $onlyMinified = (bool) $this->option('minified'); $onlyOriginal = (bool) $this->option('original'); $this->info("======================================================="); $this->info("      DAPCODE AEGISGUARD — CODE STATUS INSPECTOR       "); $this->info("======================================================="); $displayTarget = $target; if (in_array(strtolower($target), ['routes', 'route', 'portfolio', 'home'], true)) { $displayTarget = "{$target} (Seluruh File Routes, Middlewares, Helpers & Halaman Utama Portofolio)"; } elseif (in_array(strtolower($target), ['aegisguard', 'protection', 'dapcode', 'enc', 'encrypted'], true)) { $displayTarget = "{$target} (Kode Proteksi AegisGuard & File Enkripsi .enc)"; } elseif (in_array(strtolower($target), ['middlewares', 'middleware'], true)) { $displayTarget = "{$target} (Seluruh File Middleware & Http/Kernel.php)"; } elseif (in_array(strtolower($target), ['helpers', 'helper'], true)) { $displayTarget = "{$target} (Seluruh File Helper)"; } elseif (in_array(strtolower($target), ['kernel', 'http-kernel'], true)) { $displayTarget = "{$target} (File Http/Kernel.php)"; } $this->line("<comment>Target     :</comment> <info>{$displayTarget}</info>"); if ($onlyMinified) { $this->line("<comment>Filter     :</comment> <info>Hanya File Minified</info>"); } elseif ($onlyOriginal) { $this->line("<comment>Filter     :</comment> <info>Hanya File Original / Format</info>"); } $this->newLine(); $files = $minifier->getTargetFiles($target); if (empty($files)) { $this->error("Tidak ada file yang ditemukan untuk target [{$target}]."); return 1; } $tableRows = []; $totalFiles = count($files); $minifiedCount = 0; $originalCount = 0; $vaultedCount = 0; $totalSize = 0; foreach ($files as $filePath) { $stat = $minifier->getFileStatus($filePath); if ( ! $stat) { continue; } $totalSize += $stat['size']; if ($stat['is_minified']) { $minifiedCount++; } else { $originalCount++; } if ($stat['has_vault']) { $vaultedCount++; } if ($onlyMinified && ! $stat['is_minified']) { continue; } if ($onlyOriginal && $stat['is_minified']) { continue; } $typeLabel = $stat['type']; if ($stat['type'] === 'PHP') { $typeLabel = '<comment>PHP</comment>'; } elseif ($stat['type'] === 'Blade') { $typeLabel = '<info>Blade</info>'; } elseif ($stat['type'] === 'JSON') { $typeLabel = '<fg=cyan>JSON</>'; } elseif ($stat['type'] === 'ENC') { $typeLabel = '<question>ENC</question>'; } $statusLabel = $stat['is_minified'] ? '<info>⚡ MINIFIED</info>' : '<comment>📄 ORIGINAL</comment>'; $vaultLabel = $stat['has_vault'] ? '<info>✓ Vaulted</info>' : '<fg=gray>- None -</>'; $lineText = $stat['lines'] === 1 ? '1 line' : "{$stat['lines']} lines"; $tableRows[] = [ 'file' => $stat['rel_path'], 'type' => $typeLabel, 'status' => $statusLabel, 'lines' => $lineText, 'size' => $this->formatBytes($stat['size']), 'vault' => $vaultLabel, ]; } $this->table(['File Target', 'Type', 'Status', 'Lines', 'Size', 'SourceMap Vault'], $tableRows ); $minifiedPercent = $totalFiles > 0 ? round(($minifiedCount / $totalFiles) * 100, 1) : 0; $originalPercent = $totalFiles > 0 ? round(($originalCount / $totalFiles) * 100, 1) : 0; $vaultedPercent = $totalFiles > 0 ? round(($vaultedCount / $totalFiles) * 100, 1) : 0; $this->info("======================================================="); $this->info(" [SUMMARY] Status Analisis ({$totalFiles} file target):"); $this->line(" ⚡ Minified Files     : <info>{$minifiedCount}</info> file ({$minifiedPercent}%)"); $this->line(" 📄 Original Files     : <comment>{$originalCount}</comment> file ({$originalPercent}%)"); $this->line(" 🔒 SourceMap Vaulted  : <info>{$vaultedCount}</info> file ({$vaultedPercent}%)"); $this->line(" 💾 Total Ukuran File  : <info>" . $this->formatBytes($totalSize) . "</info>"); $this->newLine(); if ($minifiedCount < $totalFiles) { $this->line(" 💡 Jalankan <info>php artisan code:minify {$target}</info> untuk mengompres file."); } if ($minifiedCount > 0) { $this->line(" 💡 Jalankan <info>php artisan code:unminify {$target}</info> untuk memulihkan file asli."); } $this->info("======================================================="); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }